export const WORLD_COUNTRIES_BY_CODE: Record<string, WorldCountry> = Object.fromEntries(
  WORLD_COUNTRIES.map((c) => [c.code, c])
);

export const CONTINENTS: Continent[] = ['Africa', 'Europe', 'Asia', 'Americas', 'Oceania'];

export function getCountriesByContinent(continent?: Continent): WorldCountry[] {
  if (!continent) return WORLD_COUNTRIES;
  return WORLD_COUNTRIES.filter((c) => c.continent === continent);
}

export function getRandomCountry(continent?: Continent): WorldCountry {
  const list = getCountriesByContinent(continent);
  return list[Math.floor(Math.random() * list.length)]!;
}
